def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    L = 10 ** 12
    def cube():
        return rng.randint(-10 ** 4, 10 ** 4) ** 3
    def near():
        return cube() + rng.choice([-2, -1, 1, 2])
    def rnd():
        return rng.randint(-L, L)
    def mix(n):
        out = []
        for _ in range(n):
            t = rng.random()
            out.append(cube() if t < 0.4 else near() if t < 0.7 else rnd())
        return out
    tests = [fmt([0]), fmt([1]), fmt([-1]), fmt([2]), fmt([8, 9, 27, -64, 0, 100]),
             fmt([L, -L, L - 1, -L + 1, 9999 ** 3, 9999 ** 3 + 1, -(9999 ** 3) - 1]),
             fmt([7, 7, 7, 8, 8, 8]), fmt([-8, -7, -9, -27, -26]), fmt([L, 999999999999, -L, L])]
    for n in (3, 6, 10, 15, 25):
        for _ in range(2):
            tests.append(fmt(mix(n)))
    tests.append(fmt(mix(100000)))
    tests.append(fmt([cube() for _ in range(100000)]))
    tests.append(fmt([rnd() for _ in range(100000)]))
    tests.append(fmt([rng.randint(9000, 10000) ** 3 + rng.choice([0, 0, 1, -1]) for _ in range(100000)]))
    return tests

